#!/usr/bin/env python3
"""Prints the generated parts of ../PROOF.bend (deep patterns on words and
lists that are tedious to write by hand); PROOF.bend holds them after
"# generated by gen/proof_lemmas.py (PART)" lines. Run it and paste a part:

    proof_lemmas.py words | chunks | groups | lens | starts | pointer_laws |
                    first_pointers | lit_fits | field_fits
"""
import sys


def u32_pat(k, last="r"):
    s = last
    for i in range(k - 1, -1, -1):
        s = "WCon{c%d, %s}" % (i, s)
    return "U32{%s}" % s


def words():
    out = []
    out.append("# rebyte(x) is B.byte(x): both read x's low 8 bits")
    out.append("def rebyte_byte(+x: U32) -> {Bi.c842.rebyte(x) == B.byte(x) : U32}:")
    out.append("  match x:")
    out.append("    case %s:" % u32_pat(8, "hi"))
    out.append("      {==}")
    out.append("")
    out.append("# reword(x) is x: all 32 bits")
    out.append("def reword_id(+x: U32) -> {Bi.c842.reword(x) == x : U32}:")
    out.append("  match x:")
    out.append("    case %s:" % u32_pat(32, "WNil{}"))
    out.append("      {==}")
    return "\n".join(out)


def chunks():
    """lit_main's case tree: xs as 0 to 7 bytes, or 8 and more."""
    out = []
    names = ["b%d" % i for i in range(8)]
    st = "D.C842Going{acc, n, w, Nat.add(List.length(&2, U32, XS), k)}"
    def xs_of(i, tail):
        s = tail
        for j in range(i - 1, -1, -1):
            s = "Con{b%d, %s}" % (j, s)
        return s
    ind = "  "
    out.append(ind + "match xs:")
    for i in range(8):
        pad = ind + "  " * (2 * i)
        if i > 0:
            pass
        out.append(pad + "  case Nil{}:")
        out.append(pad + "    {==}")
        out.append(pad + "  case Con{b%d, t%d}:" % (i, i + 1))
        out.append(pad + "    match t%d:" % (i + 1))
    pad = ind + "  " * 16
    # t8 is the rest after 8 bytes: an induction step
    acc8 = "acc"
    n8 = "n"
    w8 = "w"
    for i in range(8):
        w8 = "W.c842.win.put(%s, %s, Bi.c842.rebyte(b%d))" % (w8, n8, i)
        acc8 = "Con{Bi.c842.rebyte(b%d), %s}" % (i, acc8)
        n8 = "U32.add(%s, 1)" % n8
    # the last match level was "match t8:" — replace with direct call on t8
    out[-1] = " " * 34 + "lit_main(t8, c, r, %s, %s, %s, k)" % (acc8, n8, w8)
    return "\n".join(out)


def groups():
    """unpack_group's and mask_group's partial cases: 1 to 7 bits."""
    out = []
    for name, goal in (("unpack_group", "{F.c842.unpack.list(F.c842.fmt.group(XS)) == F.c842.fmt.cat(XS, F.c842.fmt.zeros(F.c842.fmt.gfill(XS))) : List<&2, Bool>}"),
                       ("mask_group", "{B.mask(F.c842.fmt.group(XS)) == F.c842.fmt.group(XS) : List<&2, U32>}")):
        out.append("def %s(+bs: List<&2, Bool>) -> %s:" % (name, goal.replace("XS", "bs")))
        out.append("  match bs:")
        for i in range(8):
            pad = "  " + "  " * (2 * i)
            out.append(pad + "  case Nil{}:")
            out.append(pad + "    {==}")
            out.append(pad + "  case Con{c%d, t%d}:" % (i, i + 1))
            out.append(pad + "    match t%d:" % (i + 1))
        pad = "  " + "  " * 16
        xs = "t8"
        for j in range(7, -1, -1):
            xs = "Con{c%d, %s}" % (j, xs)
        if name == "unpack_group":
            rhs = "_"
            for j in range(7, -1, -1):
                rhs = "Con{c%d, %s}" % (j, rhs)
            p = "{F.c842.unpack.list(F.c842.fmt.group(%s)) == %s : List<&2, Bool>}" % (xs, rhs)
        else:
            p = "{B.mask(F.c842.fmt.group(%s)) == Con{Bi.c842.byte.of(c7, c6, c5, c4, c3, c2, c1, c0), _} : List<&2, U32>}" % xs
        out[-1] = " " * 34 + "%%%s(t8) : %s" % (name, p)
        out.append(" " * 34 + "{==}")
        out.append("")
    return "\n".join(out)


def lens():
    """lit_len's case tree: the literal stream's bits, counted."""
    out = []
    out.append("  match xs:")
    for i in range(8):
        pad = "  " + "  " * (2 * i)
        out.append(pad + "  case Nil{}:")
        out.append(pad + "    {==}")
        out.append(pad + "  case Con{b%d, t%d}:" % (i, i + 1))
        out.append(pad + "    match t%d:" % (i + 1))
    xs = "t8"
    for j in range(7, -1, -1):
        xs = "Con{b%d, %s}" % (j, xs)
    out[-1] = " " * 34 + "%%lit_len(t8, c) : {List.length(&2, Bool, F.c842.serialise(C.c842.enc.lits(%s, c))) == Nat.add(69n, _) : Nat}" % xs
    out.append(" " * 34 + "{==}")
    return "\n".join(out)


def starts():
    """The laws on streams that cannot start: the first byte (and the
    second, for RPT's field) split into bits, then the decoder fails and
    takes no more."""
    def u32(k, last, v="c"):
        s = last
        for i in range(k - 1, -1, -1):
            s = "WCon{%s%d, %s}" % (v, i, s)
        return "U32{%s}" % s

    def law(name, first, err, second=False):
        R = "Result<&2, &2, E.C842Error, B.Octets>"
        goal_tail = "== Fail{E.%s{}} : %s}" % (err, R)
        out = []
        if first == 232:
            X = "232"
            params = "rest, max"
        else:
            params = "lo, b, rest, max" if second else "lo, rest, max"
        out.append("def Laws.%s(%s):" % (name, params))
        ind = "  "
        if first != 232:
            out.append(ind + "match lo:")
            out.append(ind + "  case %s:" % u32(32, "WNil{}"))
            ind += "    "
            X = "U32.or(%d, U32.and(7, %s))" % (first, u32(32, "WNil{}"))
        if second:
            Bv = u32(8, "bh", "d")
            out.append(ind + "match b:")
            out.append(ind + "  case %s:" % Bv)
            ind += "    "
            inner = "B.Octets.cons(%s, rest)" % Bv
        else:
            inner = "rest"
        out.append(ind + "%%Equal.sym(List<&2, U32>, B.Octets.to_list(B.Octets.cons(%s, %s)), Con{B.byte(%s), B.Octets.to_list(%s)}, BL.octets_cons_list(%s, %s)) : {D.c842.dec.result(D.c842.dec.go(F.c842.unpack.list(_), D.c842.dec.start(max))) %s" % (X, inner, X, inner, X, inner, goal_tail))
        if second:
            out.append(ind + "%%Equal.sym(List<&2, U32>, B.Octets.to_list(%s), Con{B.byte(%s), B.Octets.to_list(rest)}, BL.octets_cons_list(%s, rest)) : {D.c842.dec.result(D.c842.dec.go(F.c842.unpack.list(Con{B.byte(%s), _}), D.c842.dec.start(max))) %s" % (inner, Bv, Bv, X, goal_tail))
        tl = "B.Octets.to_list(rest)"
        out.append(ind + "%%Equal.sym(D.C842Dec, D.c842.dec.go(F.c842.unpack.list(%s), D.C842Dec{F.c842.parse.code_next(), D.C842Failed{E.%s{}}}), D.C842Dec{F.c842.parse.code_next(), D.C842Failed{E.%s{}}}, absorb_fail(F.c842.unpack.list(%s), F.c842.parse.code_next(), E.%s{})) : {D.c842.dec.result(_) %s" % (tl, err, err, tl, err, goal_tail))
        out.append(ind + "{==}")
        return "\n".join(out)

    return "\n\n".join([law("code26_rejected", 208, "C842BadTemplate"),
                        law("code31_rejected", 248, "C842BadTemplate"),
                        law("repeat_first_rejected", 216, "C842BadRepeat", True),
                        law("short_zero_rejected", 232, "C842BadShort")]) + "\n"


# The pointer rule's laws, per kind: (code of a template that opens with the
# kind, its constructor, index width, log2 of the size, size, history, history
# - 1, the history's bits, size - 1, history / size)
POINTER_KINDS = {
    "P8": (200, "F.C842P8{}", 8, "3n", 8, 2048, "2047n", "11", "7n", "256n"),
    "P4": (160, "F.C842P4{}", 9, "2n", 4, 2048, "2047n", "11", "3n", "512n"),
    "P2": (80, "F.C842P2{}", 8, "1n", 2, 512, "511n", "9", "1n", "256n"),
}


def bits_list(xs):
    s = "Nil{}"
    for x in reversed(xs):
        s = "Con{%s, %s}" % (x, s)
    return s


def kind_facts(name):
    code, ctor, wb, sh, size, hist, hp, kh, sp, q = POINTER_KINDS[name]
    R = "Nat.mul(U32.to_nat(i), %dn)" % size
    mul = {8: "PP.cp.mul8(i)", 4: "PP.cp.mul4(i)", 2: "PP.cp.mul2(i)"}[size]
    vr = "PP.cp.vr(i, %d, %s, %d, %s, h)" % (size, sh, hist, mul)
    hp0 = "PP.cp.hp%s(w, %d, i, %s, %s, h)" % (kh, size, R, vr)
    return code, ctor, wb, sh, size, hist, hp, kh, sp, q, R, hp0


def pointer_laws():
    """pointer_found and pointer_rule: n split into its word, then one case
    per kind, each the generic lemma of proof_pointer.bend with the kind's
    facts."""
    out = []
    out.append("def Laws.pointer_found(n, k, i, h):")
    out.append("  match n:")
    out.append("    case U32{w}:")
    out.append("      match k:")
    out.append("        case F.C842LL{}:")
    out.append("          PP.cp.absurd({Maybe.is_some(&2, U32, P.c842.pointer(U32{w}, F.C842LL{}, i)) == Nat.is_lt(Laws.C842Laws.is(i, F.C842LL{}), Laws.C842Laws.t8(U32{w})) : Bool}, ll_absurd(i, h))")
    for name in ["P2", "P4", "P8"]:
        code, ctor, wb, sh, size, hist, hp, kh, sp, q, R, hp0 = kind_facts(name)
        out.append("        case %s:" % ctor)
        out.append("          %%PP.cp.et(w) : {Maybe.is_some(&2, U32, P.c842.pointer(U32{w}, %s, i)) == Nat.is_lt(%s, _) : Bool}" % (ctor, R))
        out.append("          PP.cp.g_found(PP.cp.p0(w, %d, %d, i), PP.cp.t8(w), %d, PP.cp.b%s(w), PP.cp.r%s(w), %s, %s, PP.cp.ht%s(w), %s, {==}, h)" % (hist, size, hist, kh, kh, R, hp, kh, hp0))
    out.append("")
    out.append("def Laws.pointer_rule(n, k, i, p, h, e):")
    out.append("  match n:")
    out.append("    case U32{w}:")
    out.append("      match k:")
    out.append("        case F.C842LL{}:")
    out.append("          PP.cp.absurd({(Nat.mod(U32.to_nat(p), U32.to_nat(F.C842Kind.history(F.C842LL{}))), Nat.is_le(Nat.add(U32.to_nat(p), U32.to_nat(F.C842Kind.size(F.C842LL{}))), Laws.C842Laws.t8(U32{w})), Nat.is_le(Laws.C842Laws.t8(U32{w}), Nat.add(U32.to_nat(p), U32.to_nat(F.C842Kind.history(F.C842LL{}))))) == (Laws.C842Laws.is(i, F.C842LL{}), True{}, True{}) : Nat & Bool & Bool}, ll_absurd(i, h))")
    xexpr = {"P8": "PP.cp.dv(w)", "P4": "Nat.mul(PP.cp.dv(w), 2n)", "P2": "Nat.mul(PP.cp.dv(w), 4n)"}
    for name in ["P2", "P4", "P8"]:
        code, ctor, wb, sh, size, hist, hp, kh, sp, q, R, hp0 = kind_facts(name)
        if name == "P8":
            hx = "PP.cp.vt8(w)"
        else:
            f = {"P4": 2, "P2": 4}[name]
            hx = ("Equal.trans(Nat, U32.to_nat(PP.cp.t8(w)), Nat.mul(PP.cp.dv(w), 8n), Nat.mul(Nat.mul(PP.cp.dv(w), %dn), %dn), PP.cp.vt8(w), "
                  "Equal.sym(Nat, Nat.mul(Nat.mul(PP.cp.dv(w), %dn), %dn), Nat.mul(PP.cp.dv(w), Nat.mul(%dn, %dn)), PP.cp.mul_assoc(PP.cp.dv(w), %dn, %dn)))") % (f, size, f, size, f, size, f, size)
        out.append("        case %s:" % ctor)
        out.append("          %%PP.cp.et(w) : {(Nat.mod(U32.to_nat(p), %dn), Nat.is_le(Nat.add(U32.to_nat(p), %dn), _), Nat.is_le(_, Nat.add(U32.to_nat(p), %dn))) == (%s, True{}, True{}) : Nat & Bool & Bool}" % (hist, size, hist, R))
        out.append("          PP.cp.g_some(PP.cp.p0(w, %d, %d, i), PP.cp.t8(w), %d, p, PP.cp.b%s(w), PP.cp.r%s(w), %s, %s, %s, %s, %s, U32.to_nat(i), PP.cp.ht%s(w), %s, {==}, PP.cp.hrr%s(w), h, {==}, %s, {==}, e)" % (hist, size, hist, kh, kh, R, hp, sp, q, xexpr[name], kh, hp0, kh, hx))
    return "\n".join(out)


def first_pointers():
    """The laws on streams that open with a pointer: the two bytes split
    into bits, the parser reads the index, and the rule at n = 0 has no
    position (none0); then the decoder fails and takes no more."""
    res = "Result<&2, &2, E.C842Error, B.Octets>"
    parts = []
    for name in ["P8", "P4", "P2"]:
        code, ctor, wb, sh, size, hist, hp, kh, sp, q, R, hp0 = kind_facts(name)
        lo = u32_pat(32, "WNil{}")
        b = u32_pat(8, "bh").replace("WCon{c", "WCon{d")
        b0 = "U32.or(%d, U32.and(7, %s))" % (code, lo)
        nd = wb - 3
        arrival = ["c2", "c1", "c0"] + ["d%d" % (7 - j) for j in range(nd)]
        got = list(reversed(arrival))
        rem = ["d%d" % (7 - j) for j in range(nd, 8)]
        idx = "F.c842.fmt.value(%s)" % bits_list(got)
        pst = {"P8": "F.c842.parse.code_next()",
               "P4": "F.c842.parse.want(F.C842WField{F.C842LL{}, [F.C842LL{}]}, 16n)",
               "P2": "F.c842.parse.want(F.C842WField{F.C842LL{}, [F.C842LL{}, F.C842LL{}]}, 16n)"}[name]
        hidx = "PP.cp.mulb(U32.to_nat(%s), %s, %dn, PP.cp.vb(%s, {==}))" % (idx, sh, wb, bits_list(got))
        out = []
        out.append("def Laws.first_%s_rejected(lo, b, rest, max):" % name.lower())
        out.append("  match lo:")
        out.append("    case %s:" % lo)
        out.append("      match b:")
        out.append("        case %s:" % b)
        out.append("          %%Equal.sym(List<&2, U32>, B.Octets.to_list(B.Octets.cons(%s, B.Octets.cons(%s, rest))), Con{B.byte(%s), B.Octets.to_list(B.Octets.cons(%s, rest))}, BL.octets_cons_list(%s, B.Octets.cons(%s, rest))) : {D.c842.dec.result(D.c842.dec.go(F.c842.unpack.list(_), D.c842.dec.start(max))) == Fail{E.C842BadPointer{}} : %s}" % (b0, b, b0, b, b0, b, res))
        out.append("          %%Equal.sym(List<&2, U32>, B.Octets.to_list(B.Octets.cons(%s, rest)), Con{B.byte(%s), B.Octets.to_list(rest)}, BL.octets_cons_list(%s, rest)) : {D.c842.dec.result(D.c842.dec.go(F.c842.unpack.list(Con{B.byte(%s), _}), D.c842.dec.start(max))) == Fail{E.C842BadPointer{}} : %s}" % (b, b, b, b0, res))
        out.append("          %%none0(%s, %s, %s) : {D.c842.dec.result(D.c842.dec.go(F.c842.unpack.list(B.Octets.to_list(rest)), D.c842.dec.go(%s, D.C842Dec{%s, D.c842.dec.ptr.at(_, %s, D.C842Going{Nil{}, 0, W.c842.win.empty(), max})}))) == Fail{E.C842BadPointer{}} : %s}" % (ctor, idx, hidx, bits_list(rem), pst, ctor, res))
        out.append("          %%Equal.sym(D.C842Dec, D.c842.dec.go(F.c842.unpack.list(B.Octets.to_list(rest)), D.C842Dec{%s, D.C842Failed{E.C842BadPointer{}}}), D.C842Dec{%s, D.C842Failed{E.C842BadPointer{}}}, absorb_fail(F.c842.unpack.list(B.Octets.to_list(rest)), %s, E.C842BadPointer{})) : {D.c842.dec.result(_) == Fail{E.C842BadPointer{}} : %s}" % (pst, pst, pst, res))
        out.append("          {==}")
        parts.append("\n".join(out))
    return "\n\n".join(parts)


def lit_fits():
    """A literal's event fits: parse.lit's 16-bit pattern, case by case."""
    lines = ["def pi_lit(+bs: List<&2, Bool>) -> {Laws.C842Laws.fits(F.c842.parse.lit(bs)) == True{} : Bool}:"]
    ind = "  "
    var = "bs"
    for d in range(16):
        lines.append(ind + "match %s:" % var)
        lines.append(ind + "  case Nil{}:")
        lines.append(ind + "    {==}")
        lines.append(ind + "  case Con{c%d, t%d}:" % (d, d + 1))
        ind += "    "
        var = "t%d" % (d + 1)
    lines.append(ind + "{==}")
    return "\n".join(lines)


def field_fits():
    """A pointer field of width(k) bits fits: its value is below 2^width
    (cp.vb), so i * s < H (cp.mulb)."""
    out = ["def pi_field(+k: F.C842Kind, +bs: List<&2, Bool>, +e: {List.length(&2, Bool, bs) == F.C842Kind.width(k) : Nat}) -> {Laws.C842Laws.fits(F.c842.parse.field(k, bs)) == True{} : Bool}:",
           "  match k:",
           "    case F.C842LL{}:",
           "      pi_lit(bs)"]
    for ctor, wb, sh in [("F.C842P2{}", 8, "1n"), ("F.C842P4{}", 9, "2n"), ("F.C842P8{}", 8, "3n")]:
        V = "U32.to_nat(F.c842.fmt.value(bs))"
        L = "List.length(&2, Bool, bs)"
        hl = "PP.cp.le_rw(%dn, %s, 9n, 9n, Equal.sym(Nat, %s, %dn, e), {==}, {==})" % (wb, L, L, wb)
        vb = "PP.cp.vb(bs, %s)" % hl
        hv = "PP.cp.lt_rw(%s, %s, U.U32Nat.dbl(%s, 1n), U.U32Nat.dbl(%dn, 1n), {==}, Equal.cong(Nat, Nat, z => U.U32Nat.dbl(z, 1n), %s, %dn, e), %s)" % (V, V, L, wb, L, wb, vb)
        out.append("    case %s:" % ctor)
        out.append("      PP.cp.mulb(%s, %s, %dn, %s)" % (V, sh, wb, hv))
    return "\n".join(out)


print({"words": words, "chunks": chunks, "groups": groups, "lens": lens, "starts": starts,
       "pointer_laws": pointer_laws, "first_pointers": first_pointers, "lit_fits": lit_fits, "field_fits": field_fits}[sys.argv[1]]())
